-/*
- * Tailwind v4, CSS-first. `@theme inline` aliases Tailwind's generated
- * utilities to the runtime tokens in tokens.css instead of baking in static
- * values — so `bg-accent`, `text-fg-muted`, etc. keep responding to the
- * [data-theme="dark"] switch. This file owns zero color literals; every
- * value here is a `var()` reference back to tokens.css, which stays the one
- * palette authority (see tokens.css's header comment).
- */
-@import "tailwindcss";
-
-@theme inline {
-  --color-bg: var(--bg);
-  --color-bg-1: var(--bg-1);
-  --color-bg-2: var(--bg-2);
-  --color-bg-3: var(--bg-3);
-  --color-fg: var(--fg);
-  --color-fg-secondary: var(--fg-secondary);
-  --color-fg-muted: var(--fg-muted);
-  --color-fg-faint: var(--fg-faint);
-  --color-border: var(--border);
-  --color-border-strong: var(--border-strong);
-  --color-accent: var(--accent);
-  --color-accent-2: var(--accent-2);
-  --color-node: var(--node);
-  --color-out-bg: var(--out-bg);
-  --color-out-fg: var(--out-fg);
-  --color-t-nonterm: var(--t-nonterm);
-  --color-t-term: var(--t-term);
-  --color-t-action: var(--t-action);
-  --color-t-op: var(--t-op);
-  --color-t-comment: var(--t-comment);
-
-  --font-ui: var(--font-ui);
-  --font-mono: var(--font-mono);
-
-  --radius-DEFAULT: var(--radius);
-  --radius-lg: var(--radius-lg);
-
-  --shadow-card: var(--shadow-card);
-  --shadow-pop: var(--shadow-pop);
-}
